# Look for Fable-related files
result = []
for root, dirs, files in os.walk(base):
    # Skip backup dirs and .git
    dirs[:] = [d for d in dirs if not d.startswith('backup') and d != '.git' and d != '__pycache__' and d != '.pytest_cache']
